         serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
@@ -701,4 +766,106 @@ app_name: ProjectApp
         let config = load_merged_config(temp.path()).unwrap();
         assert_eq!(config.app_name, Some("NoExtends".to_string()));
     }
+
+    #[test]
+    fn parse_config_rejects_unknown_top_level_fields() {
+        let content = r#"
+app_name: TestApp
+unknown_field: value
+stps:
+  test:
+    command: echo test
+"#;
+        let result = parse_config(content, Path::new("test.yml"));
+        assert!(result.is_err());
+        let err = result.unwrap_err();
+        match &err {
+            BivvyError::ConfigParseError { message, .. } => {
+                assert!(
+                    message.contains("unknown_field"),
+                    "Error should mention 'unknown_field', got: {}",
+                    message
+                );
+                assert!(
+                    message.contains("stps"),
+                    "Error should mention 'stps', got: {}",
+                    message
+                );
+            }
+            other => panic!("Expected ConfigParseError, got: {:?}", other),
+        }
+    }
+
+    #[test]
+    fn parse_config_accepts_all_known_fields() {
+        let content = r#"
+app_name: TestApp
+settings:
+  default_output: quiet
+template_sources: []
+steps:
+  test:
+    command: echo test
+workflows:
+  default:
+    steps: [test]
+secrets: {}
+requirements: {}
+vars: {}
+"#;
+        let result = parse_config(content, Path::new("test.yml"));
+        assert!(
+            result.is_ok(),
+            "Valid config should parse: {:?}",
+            result.err()
+        );
+    }
+
+    #[test]
+    fn load_merged_config_rejects_unknown_fields() {
+        let temp = TempDir::new().unwrap();
+        let bivvy_dir = temp.path().join(".bivvy");
+        fs::create_dir_all(&bivvy_dir).unwrap();
+        fs::write(
+            bivvy_dir.join("config.yml"),
+            "app_name: Test\ntypo_field: oops\n",
+        )
+        .unwrap();
+
+        let result = load_merged_config(temp.path());
+        assert!(result.is_err());
+        match result.unwrap_err() {
+            BivvyError::ConfigParseError { message, .. } => {
+                assert!(
+                    message.contains("typo_field"),
+                    "Error should mention 'typo_field', got: {}",
+                    message
+                );
+            }
+            other => panic!("Expected ConfigParseError, got: {:?}", other),
+        }
+    }
+
+    #[test]
+    fn load_merged_config_rejects_unknown_fields_from_local_override() {
+        let temp = TempDir::new().unwrap();
+        let bivvy_dir = temp.path().join(".bivvy");
+        fs::create_dir_all(&bivvy_dir).unwrap();
+
+        fs::write(bivvy_dir.join("config.yml"), "app_name: Test\n").unwrap();
+        fs::write(bivvy_dir.join("config.local.yml"), "bogus_setting: true\n").unwrap();
+
+        let result = load_merged_config(temp.path());
+        assert!(result.is_err());
+        match result.unwrap_err() {
+            BivvyError::ConfigParseError { message, .. } => {
+                assert!(
+                    message.contains("bogus_setting"),
+                    "Error should mention 'bogus_setting', got: {}",
+                    message
+                );
+            }
+            other => panic!("Expected ConfigParseError, got: {:?}", other),
+        }
+    }
 }

